loadOrder();
const ok=(x,f)=>(f.p=="a"||x.p==f.p||x.p=="a")&&(f.t=="a"||!x.t||x.t==f.t||(f.t=="l"&&x.t=="n"))&&(f.s=="a"||x.s==f.s)&&(f.cat=="a"||!x.cat||x.cat==f.cat)&&(f.car!="n"||!x.r);
function opts(L,f,cap){
 for(const g of [f,{...f,s:"a"},{...f,s:"a",t:"a"}]){const r=L.filter(x=>ok(x,g)&&x.c<=cap);if(r.length)return r}
 return [];
}
const aPool=()=>{const r=opts(A,S,Math.max(S.b-150,0));if(S.car=="y"){const car=r.filter(x=>x.r);if(car.length)return car}return r.length?r:opts(A,S,S.b)};
const fPool=()=>{const base=S.act&&S.act.t=="n"?F.filter(x=>x.k):F.filter(x=>!x.k||x.k==2);const mode=S.foodMode=="a"?base:base.filter(x=>x.m==S.foodMode);return opts(mode,{p:S.p,t:"a",s:S.s},S.act?Math.max(S.b-S.act.c,150):S.b)};
const total=()=>(S.act?S.act.c:0)+(S.food?S.food.c:0);
const CH={p:{c:"Inside CDO",m:"Outside CDO",a:"Anywhere"},car:{a:"Either",y:"I have a car",n:"No car"},b:{300:"₱300",800:"₱800",1500:"₱1,500",5000:"Splurge"},t:{a:"Any length",s:"2 hours",l:"Half day or more",n:"Overnight"},s:{a:"Either",i:"Indoor",o:"Outdoor"},cat:{a:"All categories",...CAT},foodMode:{a:"Any food style",out:"Eat out",home:"Cook at home",breakfast:"Breakfast",cafe:"Cafe & dessert",street:"Street & market",takeout:"Takeout & picnic",healthy:"Lighter & healthy",special:"Special food date"}};
function sel(label,key){return `<label class="selectfield"><span>${label}</span><select aria-label="${label}" onchange="setf('${key}',this.value)">${Object.entries(CH[key]).map(([v,t])=>`<option value="${v}"${String(S[key])==v?" selected":""}>${t}</option>`).join("")}</select></label>`}
function filters(){
 const cu=S.view=="custom";
 return `<a class="back" href="#home">Back</a>
 <div class="steps"><span class="on">1 Choose</span><span${cu||S.gen?' class="on"':""}>2 Your plan</span><span>3 Kit</span></div>
 <h2>${cu?"Build your own date":"Surprise us"}</h2>
 <p class="mute">${cu?"Set the basics, then pick each part yourself.":"Tell us the basics and we choose the rest."}</p>
 ${sel("Where","p")}${sel("Do you have a car?","car")}${sel("Category","cat")}${sel("Food style","foodMode")}<label class="selectfield"><span>Budget for two</span><input class="budgetinput" type="number" min="0" step="50" inputmode="numeric" value="${S.b||""}" placeholder="e.g. 800" aria-label="Budget for two" oninput="setBudget(this.value)"><small>Enter your actual total budget for both of you.</small></label>${sel("How long","t")}${sel("Setting","s")}`
 +(cu?"":`<button class="go" onclick="gen()" ${S.b>0?"":"disabled"}>Plan my date</button>`);
}
function slot(label,key,pool,item){
 const cu=S.view=="custom",L=key=="act"?A:F;
 return `<div class="card"><div class="lab">${label}</div>`
 +(cu?`<select aria-label="${label}" onchange="pick('${key}',this.value)"><option value="">Choose one (${pool.length} matches)</option>${pool.map(x=>`<option value="${L.indexOf(x)}"${item&&item.n==x.n?" selected":""}>${x.n}, about ${peso(x.c)}</option>`).join("")}</select>`:"")
 +(item?`<h3>${item.n}</h3><p>${item.d}</p><p class="tag">About ${peso(item.c)} for two. ${PL[item.p]}. ${CAT[item.cat]?" · "+CAT[item.cat]:""}</p>`:"")
 +`<button class="ghost" onclick="shuffle('${key}')">${cu?"Surprise me":"Try another"}</button></div>`;
}
function plan(){
 const ap=aPool();
 if(!ap.length)return `<div class="card"><p>Nothing fits that combination yet. Try a bigger budget or set the place to Anywhere.</p></div>`;
 const t=total(),bl=S.b>=5000?"your splurge budget":"your "+peso(S.b)+" budget",over=t>S.b?" That is a bit over, so try another pick.":"";
 return `<h2 style="margin-top:22px">Your date</h2>`+slot("Activity","act",ap,S.act)+slot("Food","food",fPool(),S.food)
 +(t?`<div class="total">About ${peso(t)} of ${bl}.${over}</div>`:"")
 +`<p class="note">Food ideas now include eating out, takeout, street food, cafe dates, and actual cook-together meals. Prices are rough planning estimates, so check current menus and ingredient costs before you go.</p>`
 +`<p class="brandline">♥ Date Compass${SITE?" "+SITE:""}</p><div class="bar">`+(S.view=="random"?`<button class="ghost" onclick="gen()">New plan</button>`:"")+`<button onclick="startQ()">10 questions</button><button class="ghost" onclick="startKit()">Kit card</button><button class="ghost" id="cp" onclick="copyPlan()">Copy</button></div>`;
}
